#![allow(unused_imports)]
use verus::prelude::*;

/// Given an array of i8, returns a new array where each consecutive triple is cyclically shifted left by one:
/// For every complete block of three:
///   result[i] = s[i+1] if i % 3 == 0 or 1
///   result[i] = s[i-2] if i % 3 == 2
/// The leftover 1 or 2 elements at the end are unchanged.
verus! {
    fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
        let len = s.len();
        let L = len - (len % 3);

        // Create a vector with the same length as s, initialized with zeros
        let mut result = Vec::with_capacity(len);
        let mut i = 0;
        while i < len {
            if i < L {
                match i % 3 {
                    0 | 1 => {
                        // i and i+1 both map to s[i+1]
                        // ensure i+1 < len, which holds since i < L and L is multiple of 3
                        result.push(s[i + 1]);
                    }
                    2 => {
                        // map to s[i-2]
                        result.push(s[i - 2]);
                    }
                    _ => unreachable!(),
                }
            } else {
                // last 1 or 2 elements unchanged
                result.push(s[i]);
            }
            i += 1;
        }

        // Verification: result length equals input length
        assert(result.len() == len);

        // Formal ensures specification for verification:
        // For all i:
        //   if i < L:
        //     if i % 3 == 0 or 1: result[i] = s[i+1]
        //     if i % 3 == 2: result[i] = s[i-2]
        //   else:
        //     result[i] = s[i]
        ensures({
            result.len() == s.len() &&
            forall(|i: usize| (i < L ==> (
                (i % 3 == 0 ==> result[i] == s[i + 1]) &&
                (i % 3 == 1 ==> result[i] == s[i + 1]) &&
                (i % 3 == 2 ==> result[i] == s[i - 2])
            )) &&
            (i >= L ==> result[i] == s[i])
            )
        });

        result
    }
}